        function show(v) { el.querySelector('[data-stage]').innerHTML = LK.card(v, s); el.querySelector('[data-spec]').textContent = spec[v]; el.querySelectorAll('[data-seg] button').forEach(function (b) { b.setAttribute('aria-pressed', String(b.dataset.v === v)); }); }
        el.querySelector('[data-seg]').addEventListener('click', function (e) { var b = e.target.closest('button'); if (b) show(b.dataset.v); });
